$ErrorActionPreference = 'Stop'
$Rm1Namespace = 'komtas-rm1'
$Rm1Context = 'docker-desktop'

function Invoke-Rm1Kubectl {
    param([string[]]$Arguments)
    $taskResult = & kubectl --context $Rm1Context @Arguments 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw ($taskResult -join [Environment]::NewLine)
    }
    return $taskResult
}

function Write-Rm1Object {
    param($Object)
    $taskJson = $Object | ConvertTo-Json -Depth 30 -Compress
    $taskResult = $taskJson | & kubectl --context $Rm1Context apply -f - 2>&1
    if ($LASTEXITCODE -ne 0) {
        throw ($taskResult -join [Environment]::NewLine)
    }
    $taskResult | ForEach-Object { Write-Host $_ }
}

function New-Rm1Password {
    $taskBytes = New-Object byte[] 24
    $taskGenerator = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    try { $taskGenerator.GetBytes($taskBytes) } finally { $taskGenerator.Dispose() }
    return ([BitConverter]::ToString($taskBytes)).Replace('-', '').ToLowerInvariant()
}

function Start-Rm1Job {
    param([string]$Name, [string]$Manifest)
    Invoke-Rm1Kubectl -Arguments @('-n', $Rm1Namespace, 'delete', 'job', $Name, '--ignore-not-found=true', '--wait=true') | Out-Host
    Invoke-Rm1Kubectl -Arguments @('apply', '-f', $Manifest) | Out-Host
    try {
        Invoke-Rm1Kubectl -Arguments @('-n', $Rm1Namespace, 'wait', '--for=condition=complete', "job/$Name", '--timeout=330s') | Out-Host
    } catch {
        & kubectl --context $Rm1Context -n $Rm1Namespace logs "job/$Name" --all-containers=true
        & kubectl --context $Rm1Context -n $Rm1Namespace describe job $Name
        throw
    }
    Invoke-Rm1Kubectl -Arguments @('-n', $Rm1Namespace, 'logs', "job/$Name") | Out-Host
}

Connect.ps1:
[CmdletBinding()]
param([ValidateRange(1024,65535)][int]$Port='15432',[string]$Service='all',[switch]$Disconnect)
$ErrorActionPreference='Stop'
$taskPlan=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'connections.json') -Raw | ConvertFrom-Json
$taskDir=Join-Path $PSScriptRoot '.connections'
$taskState=Join-Path $taskDir 'runtime.json'
if($Disconnect){
 if(Test-Path -LiteralPath $taskState){
  $taskSaved=Get-Content -LiteralPath $taskState -Raw | ConvertFrom-Json
  foreach($taskEntry in $taskSaved.services){
   if(-not $taskEntry.pid){continue}
   $taskProcess=Get-Process -Id $taskEntry.pid -ErrorAction SilentlyContinue
   if($taskProcess -and $taskProcess.ProcessName -match '^kubectl(\.exe)?$' -and $taskProcess.StartTime.ToUniversalTime().Ticks -eq ([datetime]$taskEntry.processStartedAt).ToUniversalTime().Ticks){$taskProcess.Kill();Write-Host ('Durduruldu: '+$taskEntry.name)}
  }
 }
 return
}
$taskKubectl=(Get-Command kubectl -ErrorAction Stop).Source
New-Item -ItemType Directory -Path $taskDir -Force | Out-Null
try{$taskLock=[IO.File]::Open((Join-Path $taskDir 'session.lock'),[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)}catch{throw 'Bu paket icin Connect zaten acik. Ayni terminali kullanin veya Connect.ps1 -Disconnect calistirin.'}
$taskChildren=@();$taskEntries=@()
try{
 $taskSelected=@($taskPlan.services | Where-Object {$Service -eq 'all' -or $_.id -eq $Service})
 if(-not $taskSelected.Count){throw 'Bilinmeyen servis. connections.json dosyasini inceleyin.'}
 foreach($taskItem in $taskSelected){
  $taskBase=if($taskItem.id -eq 'postgres'){$Port}else{[int]$taskItem.localPort}
  $taskLocal=0
  foreach($taskCandidate in $taskBase..([Math]::Min(65535,$taskBase+30))){
   $taskListener=New-Object Net.Sockets.TcpListener([Net.IPAddress]::Loopback,$taskCandidate)
   try{$taskListener.Start();$taskLocal=$taskCandidate;break}catch{}finally{$taskListener.Stop()}
  }
  if(-not $taskLocal){throw ('Bos yerel port bulunamadi: '+$taskItem.name)}
  $taskLog=Join-Path $taskDir ($taskItem.id+'-'+[Guid]::NewGuid().ToString('N'))
  $taskArgs=@('--context',$taskPlan.context,'-n',$taskPlan.namespace,'port-forward','--address=127.0.0.1',('service/'+$taskItem.service),($taskLocal.ToString()+':'+$taskItem.remotePort))
  $taskOptions=@{FilePath=$taskKubectl;ArgumentList=$taskArgs;PassThru=$true;RedirectStandardOutput=($taskLog+'.out');RedirectStandardError=($taskLog+'.err')}
  if($env:OS -eq 'Windows_NT'){$taskOptions.WindowStyle='Hidden'}
  $taskProcess=Start-Process @taskOptions
  $taskChildren+= $taskProcess
  $taskEntries+= [pscustomobject]@{id=$taskItem.id;name=$taskItem.name;localPort=$taskLocal;pid=$taskProcess.Id;processStartedAt=$taskProcess.StartTime.ToUniversalTime().ToString('o');status='starting';log=$taskLog}
 }
 $taskDeadline=[DateTime]::UtcNow.AddSeconds(45)
 while([DateTime]::UtcNow -lt $taskDeadline -and @($taskEntries | Where-Object {$_.status -eq 'starting'}).Count){
  foreach($taskEntry in $taskEntries | Where-Object {$_.status -eq 'starting'}){
   $taskProcess=$taskChildren | Where-Object {$_.Id -eq $taskEntry.pid}
   $taskText=''
   if(Test-Path -LiteralPath ($taskEntry.log+'.out')){
    $taskStream=[IO.File]::Open(($taskEntry.log+'.out'),[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite)
    $taskReader=New-Object IO.StreamReader($taskStream)
    try{$taskText=$taskReader.ReadToEnd()}finally{$taskReader.Dispose()}
   }
   if($taskProcess.HasExited){$taskEntry.status='failed'}elseif($taskText.Contains('Forwarding from 127.0.0.1:')){$taskEntry.status='ready'}
  }
  Start-Sleep -Milliseconds 200
 }
 foreach($taskEntry in $taskEntries){if($taskEntry.status -eq 'starting'){$taskEntry.status='failed'}}
 [IO.File]::WriteAllText($taskState,(@{namespace=$taskPlan.namespace;context=$taskPlan.context;services=$taskEntries}|ConvertTo-Json -Depth 8),(New-Object Text.UTF8Encoding $false))
 & (Join-Path $PSScriptRoot 'Get-Connections.ps1') -NoSecrets
 if(@($taskEntries | Where-Object {$_.status -ne 'ready'}).Count){
  foreach($taskEntry in $taskEntries | Where-Object {$_.status -ne 'ready'}){Write-Warning ('Baglanamadi: '+$taskEntry.name);if(Test-Path -LiteralPath ($taskEntry.log+'.err')){Get-Content -LiteralPath ($taskEntry.log+'.err') | Write-Host}}
  throw 'Tum tuneller acilamadi; baslatilan tuneller kapatiliyor. Deploy/pod durumunu kontrol edip Connect komutunu tekrar calistirin.'
 }
 Write-Host 'Tum yerel servisler baglandi. Bu tek terminal acik kalsin. Giris bilgileri: .\Get-Connections.ps1'
 Write-Host 'Durdurmak icin Ctrl+C; yalniz bu komutun actigi tuneller kapanir.'
 while($true){
  foreach($taskProcess in $taskChildren){if($taskProcess.HasExited){throw 'Bir tunel kapandi. Connect komutunu yeniden calistirin.'}}
  Start-Sleep -Seconds 1
 }
}finally{
 foreach($taskProcess in $taskChildren){if(-not $taskProcess.HasExited){$taskProcess.Kill();$taskProcess.WaitForExit()}}
 foreach($taskEntry in $taskEntries){$taskEntry.status='closed'}
 if($taskEntries.Count){[IO.File]::WriteAllText($taskState,(@{namespace=$taskPlan.namespace;context=$taskPlan.context;services=$taskEntries}|ConvertTo-Json -Depth 8),(New-Object Text.UTF8Encoding $false))}
 $taskLock.Dispose()
}

Deploy.ps1:
[CmdletBinding()]
param()
. (Join-Path $PSScriptRoot 'Common.ps1')
if (-not (Get-Command kubectl -ErrorAction SilentlyContinue)) { throw 'kubectl bulunamadi. Docker Desktop kurulumu ve PATH kontrol edilmeli.' }
Invoke-Rm1Kubectl -Arguments @('get', 'nodes', '--request-timeout=10s') | Out-Host
$taskClasses = (Invoke-Rm1Kubectl -Arguments @('get', 'storageclass', '-o', 'json') | Out-String) | ConvertFrom-Json
$taskDefault = @($taskClasses.items | Where-Object { $_.metadata.annotations.'storageclass.kubernetes.io/is-default-class' -eq 'true' -or $_.metadata.annotations.'storageclass.beta.kubernetes.io/is-default-class' -eq 'true' })
if ($taskDefault.Count -eq 0) { throw 'Varsayilan StorageClass bulunamadi. Docker Desktop Kubernetes depolamasi hazir olmali.' }
Invoke-Rm1Kubectl -Arguments @('apply', '-f', (Join-Path $PSScriptRoot 'k8s/namespace.yaml')) | Out-Host
$taskExistingSecret = (Invoke-Rm1Kubectl -Arguments @('-n', $Rm1Namespace, 'get', 'secret', 'rm1-credentials', '--ignore-not-found=true', '-o', 'name') | Out-String).Trim()
if (-not $taskExistingSecret) {
    $taskPod = (Invoke-Rm1Kubectl -Arguments @('-n', $Rm1Namespace, 'get', 'pvc', 'data-postgres-0', '--ignore-not-found=true', '-o', 'name') | Out-String).Trim()
    if ($taskPod) { throw 'Mevcut PVC var ancak parola Secret kayip. Yeni parola uretmeden mevcut Secret yedegini geri yukleyin.' }
    Write-Rm1Object -Object @{
        apiVersion = 'v1'; kind = 'Secret'
        metadata = @{ name = 'rm1-credentials'; namespace = $Rm1Namespace }
        type = 'Opaque'
        stringData = @{ 'admin-password' = (New-Rm1Password); 'bi-password' = (New-Rm1Password) }
    }
}
$taskSql = @{}
foreach ($taskSqlFile in Get-ChildItem -LiteralPath (Join-Path $PSScriptRoot 'sql') -Filter '*.sql') {
    $taskSql[$taskSqlFile.Name] = [IO.File]::ReadAllText($taskSqlFile.FullName)
}
Write-Rm1Object -Object @{
    apiVersion = 'v1'; kind = 'ConfigMap'
    metadata = @{ name = 'rm1-sql'; namespace = $Rm1Namespace }
    data = $taskSql
}
Invoke-Rm1Kubectl -Arguments @('apply', '-f', (Join-Path $PSScriptRoot 'k8s/postgres.yaml')) | Out-Host
Invoke-Rm1Kubectl -Arguments @('-n', $Rm1Namespace, 'rollout', 'status', 'statefulset/postgres', '--timeout=330s') | Out-Host
Start-Rm1Job -Name 'rm1-seed' -Manifest (Join-Path $PSScriptRoot 'k8s/seed-job.yaml')
Start-Rm1Job -Name 'rm1-verify' -Manifest (Join-Path $PSScriptRoot 'k8s/verify-job.yaml')
Invoke-Rm1Kubectl -Arguments @('-n', $Rm1Namespace, 'get', 'pods,svc,pvc,jobs') | Out-Host
& (Join-Path $PSScriptRoot 'Show-Access.ps1')

Run-Scenario.ps1:
[CmdletBinding()]
param()
. (Join-Path $PSScriptRoot 'Common.ps1')
$taskReportDir = Join-Path $PSScriptRoot ('reports/run-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [Guid]::NewGuid().ToString('N').Substring(0,8))
$taskEvidenceDir = Join-Path $taskReportDir 'kanitlar'
New-Item -ItemType Directory -Path $taskEvidenceDir -Force | Out-Null
$taskExecutions = @()
foreach ($taskFile in @('01-kanal-geliri.sql','02-horeca-degisim.sql','03-distributor-urun.sql','verify.sql')) {
    Write-Host "Running: $taskFile"
    $taskSql = [IO.File]::ReadAllText((Join-Path $PSScriptRoot "sql/$taskFile"))
    Copy-Item -LiteralPath (Join-Path $PSScriptRoot "sql/$taskFile") -Destination $taskEvidenceDir
    $taskStatus = 'failed'
    try {
        $global:LASTEXITCODE = 1
        $ErrorActionPreference = 'Continue'
        $taskOutput = ("SET ROLE rm1_bi;`n" + $taskSql) | & kubectl --context $Rm1Context -n $Rm1Namespace exec -i postgres-0 -- sh -c 'export PGPASSWORD="$POSTGRES_PASSWORD"; exec psql --no-psqlrc -h 127.0.0.1 -U rm1_admin -d komtas_rm1 -v ON_ERROR_STOP=1' 2>&1
        $ErrorActionPreference = 'Stop'
        if ($LASTEXITCODE -eq 0) { $taskStatus = 'passed' }
    } catch { $taskOutput = $_.Exception.Message } finally { $ErrorActionPreference = 'Stop' }
    $taskOutput | Out-Host
    [IO.File]::WriteAllText((Join-Path $taskEvidenceDir ($taskFile + '.txt')), ($taskOutput | Out-String), (New-Object Text.UTF8Encoding $false))
    $taskExecutions += @{ file = $taskFile; status = $taskStatus }
}
$taskObservation = $null
try {
    $taskReportSql = [IO.File]::ReadAllText((Join-Path $PSScriptRoot 'sql/report.sql'))
    $global:LASTEXITCODE = 1
    $ErrorActionPreference = 'Continue'
    $taskRaw = ("SET ROLE rm1_bi;`n" + $taskReportSql) | & kubectl --context $Rm1Context -n $Rm1Namespace exec -i postgres-0 -- sh -c 'export PGPASSWORD="$POSTGRES_PASSWORD"; exec psql --no-psqlrc -Atq -h 127.0.0.1 -U rm1_admin -d komtas_rm1 -v ON_ERROR_STOP=1' 2> (Join-Path $taskEvidenceDir 'report-error.txt')
    $ErrorActionPreference = 'Stop'
    if ($LASTEXITCODE -ne 0) { throw 'Database report query failed.' }
    $taskObservation = ($taskRaw | Out-String) | ConvertFrom-Json
} catch {
    [IO.File]::AppendAllText((Join-Path $taskEvidenceDir 'report-error.txt'), $_.Exception.Message)
} finally { $ErrorActionPreference = 'Stop' }
$taskProfile = Get-Content -LiteralPath (Join-Path $PSScriptRoot 'report-profile.json') -Raw -Encoding UTF8 | ConvertFrom-Json
$taskResult = @{ schemaVersion = 1; architecture = $taskProfile.architecture; architectureVersion = $taskProfile.architectureVersion; scenario = $taskProfile.scenario; generatedAt = [DateTime]::UtcNow.ToString('o'); namespace = $Rm1Namespace; executions = $taskExecutions; observation = $taskObservation }
$taskJson = $taskResult | ConvertTo-Json -Depth 12
[IO.File]::WriteAllText((Join-Path $taskReportDir 'sonuc.json'), $taskJson, (New-Object Text.UTF8Encoding $false))
$taskBase64 = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($taskJson))
$taskHtml = [IO.File]::ReadAllText((Join-Path $PSScriptRoot 'report-template.html')).Replace('__RESULT_BASE64__', $taskBase64)
[IO.File]::WriteAllText((Join-Path $taskReportDir 'rapor.html'), $taskHtml, (New-Object Text.UTF8Encoding $false))
Write-Host "Rapor: $taskReportDir/rapor.html"
Write-Host "Uygulamaya yukle: $taskReportDir/sonuc.json"
if (($taskExecutions | Where-Object { $_.status -ne 'passed' }) -or -not $taskObservation -or ($taskObservation.checks | Where-Object { $_.status -ne 'passed' })) { throw 'Deney tam dogrulanmadi. Raporu ve kanitlari inceleyin.' }

sql/verify.sql:
\pset pager off
BEGIN READ ONLY;
DO $$
DECLARE
    actual numeric;
BEGIN
    SELECT count(*) INTO actual FROM dwh.fact_sales;
    IF actual<>2016 THEN RAISE EXCEPTION 'Expected 2016 fact rows, got %',actual; END IF;
    SELECT sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) INTO actual
    FROM dwh.v_sales_detail WHERE month_start=date '2025-01-01';
    IF actual<>27820.80 THEN RAISE EXCEPTION 'January revenue mismatch: %',actual; END IF;
    SELECT sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) INTO actual
    FROM dwh.v_sales_detail WHERE month_start=date '2025-02-01';
    IF actual<>23284.80 THEN RAISE EXCEPTION 'February revenue mismatch: %',actual; END IF;
    SELECT sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) INTO actual
    FROM dwh.v_sales_detail WHERE month_start=date '2025-01-01' AND channel='HoReCa';
    IF actual<>8164.80 THEN RAISE EXCEPTION 'January HoReCa mismatch: %',actual; END IF;
    SELECT sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) INTO actual
    FROM dwh.v_sales_detail WHERE month_start=date '2025-02-01' AND channel='HoReCa';
    IF actual<>3628.80 THEN RAISE EXCEPTION 'February HoReCa mismatch: %',actual; END IF;
    SELECT sum(net_volume_liters) INTO actual FROM dwh.v_sales_detail
    WHERE month_start=date '2025-02-01' AND channel='HoReCa';
    IF actual<>819.840 THEN RAISE EXCEPTION 'February HoReCa volume mismatch: %',actual; END IF;
    SELECT count(DISTINCT country) INTO actual FROM dwh.dim_outlet;
    IF actual<>2 THEN RAISE EXCEPTION 'Country count mismatch'; END IF;
    IF has_table_privilege(current_user,'dwh.fact_sales','INSERT') THEN
        RAISE EXCEPTION 'BI user must not have INSERT permission';
    END IF;
    RAISE NOTICE 'PASS: row counts, reference totals, volume and BI read-only access';
END $$;
SELECT month_start,channel,
       sum(gross_revenue_eur-discount_amount_eur-return_amount_eur) AS net_revenue_eur,
       sum(net_volume_liters) AS volume_liters,
       round(sum(gross_revenue_eur-discount_amount_eur-return_amount_eur)/nullif(sum(net_volume_liters),0),6) AS average_price_eur_per_liter,
       count(DISTINCT outlet_key) FILTER (WHERE sold_units>returned_units) AS active_outlets
FROM dwh.v_sales_detail
GROUP BY month_start,channel ORDER BY month_start,channel;
COMMIT;

Get-Connections.ps1:
[CmdletBinding()]
param([switch]$NoSecrets)
$ErrorActionPreference='Stop'
$taskPlan=Get-Content -LiteralPath (Join-Path $PSScriptRoot 'connections.json') -Raw | ConvertFrom-Json
$taskSaved=$null;$taskState=Join-Path $PSScriptRoot '.connections/runtime.json'
if(Test-Path -LiteralPath $taskState){$taskSaved=Get-Content -LiteralPath $taskState -Raw | ConvertFrom-Json}
Write-Host ('=== RM1 | TUM BAGLANTILAR | '+$taskPlan.namespace+' ===')
foreach($taskItem in $taskPlan.services){
 $taskRuntime=if($taskSaved -and $taskSaved.namespace -eq $taskPlan.namespace){$taskSaved.services | Where-Object {$_.id -eq $taskItem.id}}else{$null}
 $taskPort=if($taskRuntime){$taskRuntime.localPort}else{$taskItem.localPort}
 $taskStatus=if($taskRuntime){$taskRuntime.status}else{'Connect henuz calistirilmadi'}
 Write-Host ('--- '+$taskItem.name+' ['+$taskStatus+']')
 $taskAddress=if($taskItem.kind -eq 'http'){'http://127.0.0.1:'+ $taskPort + $taskItem.path}else{'127.0.0.1:'+ $taskPort}
 Write-Host $taskAddress
 if($taskItem.database){Write-Host ('Database: '+$taskItem.database+' | User: '+$taskItem.username)}
 if($taskItem.id -eq 'trino'){Write-Host ('JDBC: jdbc:trino://127.0.0.1:'+$taskPort+'/models/dwh | user rm9_reader | yerel HTTP, auth yok')}
}
foreach($taskLine in $taskPlan.notes){Write-Host $taskLine}
foreach($taskExternal in $taskPlan.external){
 Write-Host ('--- '+$taskExternal.name+' | harici servis, tunel acilmaz')
 $taskFile=Join-Path $PSScriptRoot $taskExternal.settings
 if(Test-Path -LiteralPath $taskFile){
  $taskSettings=Get-Content -LiteralPath $taskFile -Raw | ConvertFrom-Json
  foreach($taskKey in @('host','apiHost','environmentId','orgId')){if($taskSettings.$taskKey){Write-Host ($taskKey+': '+$taskSettings.$taskKey)}}
 }
 Write-Host $taskExternal.command
}
if($NoSecrets){Write-Host 'Parola ve Cube JWT dahil tam bilgiler: .\Get-Connections.ps1';return}
Write-Host 'Gizli bilgiler yalniz bu terminalde gosterilir; paylasmayin. Dosyaya kaydedilmez.'
foreach($taskCredential in $taskPlan.credentials){
 try{
  $taskRaw=& kubectl --context $taskPlan.context -n $taskPlan.namespace get secret $taskCredential.secret -o json 2>$null
  if($LASTEXITCODE -ne 0){throw 'Secret yok'}
  $taskSecret=($taskRaw | Out-String)|ConvertFrom-Json
  $taskValue=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($taskSecret.data.($taskCredential.key)))
  Write-Host ($taskCredential.name+': '+$taskValue)
 }catch{Write-Host ($taskCredential.name+': henuz hazir degil; Deploy durumunu kontrol edin.')}
}
if($taskPlan.cubeToken){
 Write-Host 'Cube JWT (5 dakika):'
 try{& (Join-Path $PSScriptRoot 'Get-ApiToken.ps1')}catch{Write-Host 'Cube JWT henuz alinamadi; dashboard/pod durumunu kontrol edin.'}
}
